def classify_board(r):
    t = r["text"]; k = r["kind"]
    if k == "title": return ("LOOK-ONLY", [], "board title (page name)")
    if k == "badge": return ("LOOK-ONLY", [], "picture badge: which side of the comparison the picture shows")
    if k == "figure heading": return ("LOOK-ONLY", [], "picture heading: the state the picture shows")
    if k == "alt": return ("LOOK-ONLY", [], "picture description (alt text)")
    if k == "heading": return ("LOOK-ONLY", [], "board heading or row title")
    if t.startswith("Shot 1440 x 1300"):
        if r["board"] == "DefaultBillTo.dc.html" and r["fig"] == 23:
            return ("SPEC-CONFLICT", ["BT-D13"], "the mary.moore production Edit Customer picture is 1600 x 900, not 1440 x 1300 (BT-D13)")
        return ("LOOK-ONLY", [], "picture size (correct: the picture is 1440 x 1300)")
    for sub, cls, codes, note in BOARD_RULES:
        if sub in t: return (cls, codes, note)
    return None

